import{g as a,ae as p,r as n,B as e}from"./chunks/framework.CZ-ntRvv.js";const _=JSON.parse('{"title":"Frappe app","description":"","frontmatter":{},"headers":[],"relativePath":"docs/getting-started/frappe.md","filePath":"docs/getting-started/frappe.md","lastUpdated":1790191713000}'),t={name:"docs/getting-started/frappe.md"};function o(l,s,c,i,d,r){return p(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="frappe-app" tabindex="-1">Frappe app <a class="header-anchor" href="#frappe-app" aria-label="Permalink to “Frappe app”">​</a></h1><p>Build the frontend of a Frappe app with frappe-ui. The frontend is a Vite project inside your app, and the site serves it in production.</p><p>The examples use an app named <code>todo</code>, served at <code>/todo</code>.</p><p>The quickest start is to run <code>npm create frappe-ui@latest</code> from <code>apps/todo</code>. It does every step on this page and asks before it changes your app&#39;s files. The steps below show what it sets up, for an app you set up by hand.</p><blockquote><p>The old <code>frappe-ui-starter</code> template is for frappe-ui v0. Don&#39;t use it for a new app.</p></blockquote><div class="steps"><h3 id="create-the-frontend" tabindex="-1">Create the frontend <a class="header-anchor" href="#create-the-frontend" aria-label="Permalink to “Create the frontend”">​</a></h3><p>Create the Vite project inside your app, next to the Python package.</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_i592pt">cd</span><span class="s_2575z4"> apps/todo</span></span>
<span class="line"><span class="s_euu481">npm</span><span class="s_2575z4"> create</span><span class="s_2575z4"> vite@latest</span><span class="s_2575z4"> frontend</span><span class="s_2d41qv"> --</span><span class="s_2d41qv"> --template</span><span class="s_2575z4"> vue-ts</span></span>
<span class="line"><span class="s_i592pt">cd</span><span class="s_2575z4"> frontend</span></span></code></pre></div><p>Then follow <a href="./../getting-started#install-frappe-ui">Installation</a> from step 2 to step 5. Your app now looks like this:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_wvjl67">apps/todo/</span></span>
<span class="line"><span class="s_wvjl67">  todo/            # the Python package</span></span>
<span class="line"><span class="s_wvjl67">    www/</span></span>
<span class="line"><span class="s_wvjl67">    public/</span></span>
<span class="line"><span class="s_wvjl67">  frontend/        # the Vite project</span></span></code></pre></div><h3 id="add-the-vite-plugin" tabindex="-1">Add the Vite plugin <a class="header-anchor" href="#add-the-vite-plugin" aria-label="Permalink to “Add the Vite plugin”">​</a></h3><p>Add the frappe-ui plugin to <code>vite.config.ts</code>. Set <code>frontendRoute</code> to the path the site serves the app on.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">defineConfig</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">vite</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_4q1z3w"> vue</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">@vitejs/plugin-vue</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_4q1z3w"> frappeui</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/vite</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_edvzsf">export</span><span class="s_edvzsf"> default</span><span class="s_indoxt"> defineConfig</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  plugins</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_indoxt">frappeui</span><span class="s_13ahmt">({</span><span class="s_r4oegk"> frontendRoute</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">/todo</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span><span class="s_1jjt6x">,</span><span class="s_indoxt"> vue</span><span class="s_13ahmt">()]</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span></code></pre></div><p>With no other options, the plugin:</p><ul><li>Forwards <code>/api</code>, <code>/assets</code>, <code>/files</code>, <code>/app</code>, <code>/desk</code>, <code>/login</code> and <code>/private</code> to your bench while you develop.</li><li>Passes the page&#39;s boot data to the app as globals on <code>window</code>.</li><li>Builds into <code>todo/public/frontend</code> and copies <code>index.html</code> to <code>todo/www/todo.html</code>.</li></ul><p>The <a href="./../other/vite">Vite plugin</a> page lists every option.</p><h3 id="serve-the-app-from-the-site" tabindex="-1">Serve the app from the site <a class="header-anchor" href="#serve-the-app-from-the-site" aria-label="Permalink to “Serve the app from the site”">​</a></h3><p>Add <code>todo/www/todo.py</code>. It sends boot data to the page, and frappe-ui reads <code>csrf_token</code> from it for every request. Add anything else the app needs on first load.</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_kq5psm"> frappe</span></span>
<span class="line"></span>
<span class="line"><span class="s_kq5psm">no_cache </span><span class="s_2ekfrt">=</span><span class="s_40mev6"> 1</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span class="s_50ecpt">def</span><span class="s_indoxt"> get_context</span><span class="s_13ahmt">(</span><span class="s_25kcwm">context</span><span class="s_13ahmt">):</span></span>
<span class="line"><span class="s_kq5psm">    context</span><span class="s_1jjt6x">.</span><span class="s_kq5psm">boot </span><span class="s_2ekfrt">=</span><span class="s_1jjt6x"> {</span></span>
<span class="line"><span class="s_w1p9wo">        &quot;</span><span class="s_2575z4">csrf_token</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x">:</span><span class="s_kq5psm"> frappe</span><span class="s_1jjt6x">.</span><span class="s_kq5psm">sessions</span><span class="s_1jjt6x">.</span><span class="s_1hbl6c">get_csrf_token</span><span class="s_13ahmt">()</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_w1p9wo">        &quot;</span><span class="s_2575z4">user</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x">:</span><span class="s_kq5psm"> frappe</span><span class="s_1jjt6x">.</span><span class="s_kq5psm">session</span><span class="s_1jjt6x">.</span><span class="s_kq5psm">user</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_1jjt6x">    }</span></span></code></pre></div><p>Then send every path under <code>/todo</code> to that page in <code>todo/hooks.py</code>, so a refresh on <code>/todo/tasks/42</code> still loads the app.</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_kq5psm">website_route_rules </span><span class="s_2ekfrt">=</span><span class="s_1jjt6x"> [</span></span>
<span class="line"><span class="s_1jjt6x">    {</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">from_route</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &quot;</span><span class="s_2575z4">/todo/&lt;path:app_path&gt;</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &quot;</span><span class="s_2575z4">to_route</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &quot;</span><span class="s_2575z4">todo</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x">},</span></span>
<span class="line"><span class="s_1jjt6x">]</span></span></code></pre></div><p>Don&#39;t create <code>todo/www/todo.html</code> yourself. The build writes it.</p><h3 id="set-the-router-base" tabindex="-1">Set the router base <a class="header-anchor" href="#set-the-router-base" aria-label="Permalink to “Set the router base”">​</a></h3><p>Give the router the same path as <code>frontendRoute</code>.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> router</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> createRouter</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  history</span><span class="s_1jjt6x">:</span><span class="s_indoxt"> createWebHistory</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">/todo</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_22m8k2">  routes</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span></code></pre></div><h3 id="start-the-dev-server" tabindex="-1">Start the dev server <a class="header-anchor" href="#start-the-dev-server" aria-label="Permalink to “Start the dev server”">​</a></h3><p>Pages in development don&#39;t have a CSRF token, so turn the check off for your site. Only do this on a development site.</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_euu481">bench</span><span class="s_2d41qv"> --site</span><span class="s_2575z4"> todo.test</span><span class="s_2575z4"> set-config</span><span class="s_2575z4"> ignore_csrf</span><span class="s_40mev6"> 1</span></span>
<span class="line"><span class="s_euu481">npm</span><span class="s_2575z4"> run</span><span class="s_2575z4"> dev</span></span></code></pre></div><p>Open the app on the site&#39;s name with Vite&#39;s port. Vite uses your bench port plus 80, so a bench on <code>8000</code> means:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_wvjl67">http://todo.test:8080</span></span></code></pre></div><h3 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to “Build”">​</a></h3><p>Build the app, then commit <code>todo/public/frontend</code> and <code>todo/www/todo.html</code>.</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_euu481">npm</span><span class="s_2575z4"> run</span><span class="s_2575z4"> build</span></span></code></pre></div><p>After a deploy, the app is live at <code>https://todo.test/todo</code>.</p></div><h2 id="talking-to-the-server" tabindex="-1">Talking to the server <a class="header-anchor" href="#talking-to-the-server" aria-label="Permalink to “Talking to the server”">​</a></h2><p>The data fetching composables use the browser&#39;s session with the site, so there is nothing to set up.</p><ul><li><a href="./../data-fetching/use-call"><code>useCall</code></a> calls a whitelisted method.</li><li><a href="./../data-fetching/use-list"><code>useList</code></a>, <a href="./../data-fetching/use-doc"><code>useDoc</code></a>, <a href="./../data-fetching/use-doctype"><code>useDoctype</code></a> and <a href="./../data-fetching/use-new-doc"><code>useNewDoc</code></a> work with documents.</li><li><a href="./../other/utilities#frapperequest"><code>frappeRequest</code></a> handles any other request.</li></ul><p>File uploads go to <code>/api/method/upload_file</code>.</p><h2 id="types-for-your-doctypes" tabindex="-1">Types for your DocTypes <a class="header-anchor" href="#types-for-your-doctypes" aria-label="Permalink to “Types for your DocTypes”">​</a></h2><p>The Vite plugin can write TypeScript types for your DocTypes. List the ones you use, per app:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_indoxt">frappeui</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  frontendRoute</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">/todo</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  frappeTypes</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span><span class="s_r4oegk"> input</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span><span class="s_12xt1b"> todo</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">ToDo</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">ToDo Tag</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">]</span><span class="s_13ahmt"> }</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span></code></pre></div>`,13)])])}const u=a(t,[["render",o]]);export{_ as __pageData,u as default};
